import React, { useState, useEffect, useRef } from "react";
import "./App.css";
import maplibregl from "maplibre-gl";
import Slider from "react-slider";

function App() {
  const [year, setYear] = useState(2012);
  const mapContainer = useRef(null);
  const mapRef = useRef(null);

  useEffect(() => {
    if (mapRef.current) return; // карта уже инициализирована

	mapRef.current = new maplibregl.Map({
	  container: mapContainer.current,
	  style: "https://tiles.stadiamaps.com/styles/alidade_smooth.json", // OSM-стиль
	  center: [37.6173, 55.7558], // Москва
	  zoom: 9,
	});


    return () => {
      mapRef.current?.remove();
    };
  }, []);

  return (
    <div className="App">
      <h1>Геопортал: Выборы в Москве</h1>
      <div ref={mapContainer} id="map" />
      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>
    </div>
  );
}

export default App;
